        return ' & '.join(f'x{i+1}' if random.choice([True, False]) else f'~x{i+1}' for i in range(n))

    def min_rank(formula):
        # Simplify the formula to count distinct literals
        literals = set()
        for term in formula.split(' & '):
            if '~' in term:
                literals.add(term[2:])
            else:
                literals.add(term)
        return len(literals)

    n_values = [5, 10, 15, 20, 30, 40]
